import uuid
from typing import Literal

from pydantic import BaseModel, ConfigDict, Field

# CEFR levels from A1 (beginner) to C2 (proficient), plus native speaker.
LanguageLevel = Literal["A1", "A2", "B1", "B2", "C1", "C2", "Native"]


class Language(BaseModel):
    """Language data sent by the client; the id is generated by the server."""

    name: str = Field(min_length=1)
    level: LanguageLevel


class LanguageRead(Language):
    """Language returned by the API, including its id."""

    # Allows building from ORM objects: LanguageRead.model_validate(language_orm).
    model_config = ConfigDict(from_attributes=True)

    id: uuid.UUID
